// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.query.algebra.Count;
import org.eclipse.rdf4j.query.algebra.EmptySet;
import org.eclipse.rdf4j.query.algebra.Group;
import org.eclipse.rdf4j.query.algebra.GroupElem;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.EvidenceGuarantee;
import org.junit.jupiter.api.Test;

class PackedGlobalGroupCardinalityTest {

	@Test
	void keylessGroupProducesOnePlannedRowForAnEmptySetInput() {
		Group source = globalCount(new EmptySet());

		PackedPlanningResult result = PackedCascadesPlanner.optimize(source, OptimizationGoal.root());

		Group selected = assertInstanceOf(Group.class, result.selectedPlan());
		assertInstanceOf(EmptySet.class, selected.getArg(), selected::toString);
		assertEquals(1.0d, result.outputRows(), 0.0d,
				"A global aggregate produces one row even when its exact input is empty");
		assertEquals(1.0d, selected.getResultSizeEstimate(), 0.0d, selected::toString);
	}

	@Test
	void keyedGroupProducesNoRowsForAnEmptySetInput() {
		Group source = new Group(new EmptySet(), List.of("s"),
				List.of(new GroupElem("count", new Count(Var.of("s"), true))));

		PackedPlanningResult result = PackedCascadesPlanner.optimize(source, OptimizationGoal.root());

		Group selected = assertInstanceOf(Group.class, result.selectedPlan());
		assertEquals(List.of("s"), List.copyOf(selected.getGroupBindingNames()), selected::toString);
		assertEquals(0.0d, result.outputRows(), 0.0d,
				"A keyed aggregate over empty input has no groups");
	}

	@Test
	void scalarProviderCannotOverrideTheGlobalGroupSemanticMinimum() {
		AtomicInteger groupEstimateCalls = new AtomicInteger();
		PackedCostModel costs = (query, relationId) -> {
			if (query.materializeRelation(relationId) instanceof Group) {
				groupEstimateCalls.incrementAndGet();
				return 0.0d;
			}
			return Double.NaN;
		};

		PackedPlanningResult result = PackedCascadesPlanner.optimize(globalCount(new EmptySet()),
				OptimizationGoal.root(), costs);

		assertTrue(groupEstimateCalls.get() > 0,
				"The public scalar cost model must be observed on the actual Group relation");
		assertEquals(1.0d, result.outputRows(), 0.0d,
				"A scalar point estimate cannot lower a keyless Group below its semantic one-row result");
	}

	@Test
	void operatorRefinementCannotOverrideGlobalGroupOrKeepItsConflictingEvidence() {
		AtomicInteger groupRefinements = new AtomicInteger();
		PackedCostModel costs = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return Double.NaN;
			}

			@Override
			public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (query.materializeRelation(relationId) instanceof Group) {
					groupRefinements.incrementAndGet();
					output.setRows(0.0d, 5.0d);
					output.setEvidenceGuarantee(EvidenceGuarantee.DATABASE_EXACT);
				}
			}
		};

		PackedPlanningResult result = PackedCascadesPlanner.optimize(globalCount(new EmptySet()),
				OptimizationGoal.root(), costs);

		Group selected = assertInstanceOf(Group.class, result.selectedPlan());
		assertTrue(groupRefinements.get() > 0, "The supported model callback must refine the actual Group");
		assertEquals(1.0d, result.outputRows(), 0.0d, "Refinement cannot lower the global Group result");
		assertEquals(1.0d, selected.getDoubleMetricPlanned("plannedCardinalityRows"), 0.0d, selected::toString);
		assertEquals(0.0d, selected.getDoubleMetricPlanned("optimizer.keylessGroupProviderRefinementRows"), 0.0d,
				"The raw provider point remains separately visible");
		assertNull(selected.getStringMetricPlanned("plannedFrontierGuarantee"),
				"A guarantee attached to the rejected zero output cannot be transferred to the one-row result");
	}

	private static Group globalCount(TupleExpr input) {
		return new Group(input, List.of(), List.of(new GroupElem("count", new Count(Var.of("s"), true))));
	}
}
